        res.json({
          calls: calls,
          error: err.message
        })
      })

      request(app)
      .get('/foo')
      .expect(200, { calls: ['/foo/:bar?', '/foo'], error: 'fail' }, done)
    })

    it('should call handler in same route, if exists', function(done){
